{
  "status": "Ready",
  "current_position": {
    "confirmed": [
      {
        "id": "CP-001",
        "statement": "The slice delivers a read-only model-driven account review experience showing up to ten active synthetic accounts, ordered by createdon descending, with name and accountnumber visible.",
        "basis": "The requested observable outcome, host surface, filter, ordering, row limit, and visible fields are explicit.",
        "source_refs": [
          "Skill 6 input"
        ]
      },
      {
        "id": "CP-002",
        "statement": "The execution boundary is personal-openai, the input is synthetic, and transfer of the sanitized specialist payload and result is permitted.",
        "basis": "Evaluator-supplied delegation evidence explicitly classifies the boundary and transfer.",
        "source_refs": [
          "Evaluator-supplied external delegation evidence"
        ]
      },
      {
        "id": "CP-003",
        "statement": "The required host API contract is Xrm.WebApi and standard synthetic Microsoft Dataverse Account schema assumptions are authorized.",
        "basis": "Both constraints are explicit in the request and preserved specialist result.",
        "source_refs": [
          "Skill 6 input",
          "tests/fixtures/powercat/gold-005-result.json"
        ]
      },
      {
        "id": "CP-004",
        "statement": "The approved query contract is Xrm.WebApi.retrieveMultipleRecords(\"account\", \"?$select=name,accountnumber&$filter=statecode eq 0&$orderby=createdon desc&$top=10\").",
        "basis": "The externally executed specialist returned a successful schema-valid result under the authorized synthetic assumptions.",
        "source_refs": [
          "tests/fixtures/powercat/gold-005-result.json",
          "tests/fixtures/powercat/gold-005-result-provenance.json"
        ]
      },
      {
        "id": "CP-005",
        "statement": "The preserved specialist result passed identity, current-register, pin, classification, boundary, SHA-256, answer-schema, zero-operation, and untrusted-input gates.",
        "basis": "Evaluator-supplied evidence independently records every required result-consumption verification as successful.",
        "source_refs": [
          "tests/fixtures/powercat/gold-005-result.json",
          "tests/fixtures/powercat/gold-005-result-provenance.json",
          ".agents/skills/dataverse-webapi-query/references/answer-output.schema.json"
        ]
      }
    ],
    "assumptions": [
      {
        "id": "AS-001",
        "statement": "The Xrm.WebApi result will be presented by an Account Review web resource or equivalent supported client component opened from the model-driven app.",
        "impact": "This preserves the required Xrm.WebApi contract while providing a purpose-built, accessible review surface rather than a native saved-view query.",
        "validation_required": "Confirm the selected component is supported in the target model-driven host and can access Xrm.WebApi before implementation.",
        "source_refs": [
          "Skill 6 input"
        ]
      },
      {
        "id": "AS-002",
        "statement": "The reviewing persona receives model-driven app access and least-privilege read access to Account, including name, accountnumber, createdon, and statecode.",
        "impact": "Missing table, column, or app privileges will produce the permission state instead of results.",
        "validation_required": "Resolve the target security role and verify access in the deployment environment before release.",
        "source_refs": [
          "Prescribed security boundary"
        ]
      },
      {
        "id": "AS-003",
        "statement": "Publisher prefix, solution name, environment names, navigation placement, and telemetry destination are implementation-time configuration.",
        "impact": "These values do not change the query or slice architecture but must be resolved before packaging or deployment.",
        "validation_required": "The authorised implementation owner must record and validate each value before creating the deployable package.",
        "source_refs": [
          "Power Platform Incremental Delivery bounded-assumption rules"
        ]
      }
    ],
    "open_questions": [],
    "rejected": [
      {
        "id": "RJ-001",
        "decision": "Implement the slice solely as a native Dataverse saved view.",
        "reason": "A native saved view would not embed the required validated Xrm.WebApi query contract.",
        "reconsider_if": "The host requirement is formally changed and a query specialist validates the replacement FetchXML contract."
      },
      {
        "id": "RJ-002",
        "decision": "Access a tenant or inspect live metadata while preparing this brief.",
        "reason": "The request is synthetic and expressly prohibits authentication, tenant access, and live metadata inspection.",
        "reconsider_if": "A separately authorised organisational workflow supplies approved access and a new scoped task."
      }
    ],
    "superseded": []
  },
  "boundary": {
    "zone": "personal-openai",
    "data_classification": "synthetic",
    "cross_zone_transfer": "permitted"
  },
  "slice": {
    "outcome": "An authorised account reviewer opens Account Review in a model-driven app and receives no more than ten active synthetic accounts in descending createdon order, with only name and accountnumber displayed.",
    "entry": "The account reviewer opens the Account Review navigation item or command in the model-driven app. The client renders an accessible loading state and initiates the single approved Xrm.WebApi query.",
    "validation": "The client requires an available Xrm.WebApi host, confirms the response is a collection, validates name and accountnumber as the only rendered business fields, relies on statecode eq 0 for active-row selection, and uses a request-generation token to prevent a slower stale response from replacing a newer refresh. Missing privilege, malformed responses, and host unavailability fail safely without exposing raw service details.",
    "persistence_or_action": "One Account Review data-access module owns the read action and invokes Xrm.WebApi.retrieveMultipleRecords(\"account\", \"?$select=name,accountnumber&$filter=statecode eq 0&$orderby=createdon desc&$top=10\"). The operation is read-only and naturally repeatable; a client request-generation identifier prevents duplicate rendering and stale-response replacement. No durable write or acknowledgement occurs.",
    "feedback": "Show loading with refresh disabled, then a compact two-column result grid or an explicit empty state. Show sanitized permission, unsupported-host, and transient-query failure messages; permit retry after failures; restore focus after refresh; announce result count or failure through an accessible live region; and never display a stale response superseded by a later request.",
    "telemetry": "Emit one privacy-safe AccountReviewLoad event with a generated correlation ID, duration, returned-row count, and outcome such as success, empty, permission-denied, query-failed, malformed-response, or stale-response-discarded. Exclude account names, account numbers, record identifiers, query response bodies, tenant identifiers, environment URLs, and credentials.",
    "evidence": "Keep proof levels separate: source review establishes the embedded query and state handling; automated tests establish deterministic client behavior; package inspection establishes component and dependency integrity; deployment/configuration readback establishes app placement and role binding; runtime evidence establishes actual filtering, ordering, limiting, feedback, accessibility, telemetry, retry, and stale-response behavior in the authorised target.",
    "scope": [
      "Model-driven Account Review entry point",
      "Approved Xrm.WebApi read contract",
      "Two-column name and accountnumber presentation",
      "Loading, empty, permission, retry, failure, and stale-response states",
      "Keyboard and screen-reader behavior",
      "Privacy-safe operational telemetry",
      "Solution packaging, deployment prerequisites, evidence controls, and rollback definition"
    ],
    "exclusions": [
      "Account creation, update, deletion, activation, or deactivation",
      "Authentication, tenant access, or live metadata discovery",
      "Native saved-view or FetchXML construction",
      "Pagination beyond the first ten rows",
      "Account detail navigation or drill-down",
      "AI, Copilot, or generative functionality",
      "Deployment, role assignment, or environment modification during this brief"
    ]
  },
  "architecture": {
    "experience": [
      {
        "id": "EXP-001",
        "decision": "Provide an Account Review client surface inside the model-driven app with a two-column accessible grid and explicit loading, empty, permission, failure, retry, and stale-response states.",
        "rationale": "This is the smallest user-visible surface that can execute the required Xrm.WebApi contract and cover production-relevant states.",
        "evidence_status": "Assumption"
      },
      {
        "id": "EXP-002",
        "decision": "Preserve the order returned by the approved query and display no business columns other than name and accountnumber.",
        "rationale": "This directly implements the validated result contract without client-side reinterpretation.",
        "evidence_status": "Confirmed"
      }
    ],
    "data": [
      {
        "id": "DAT-001",
        "decision": "Use logical table account, entity set accounts, attributes name, accountnumber, createdon, and statecode, with statecode 0 representing Active under the authorised standard synthetic schema.",
        "rationale": "These schema facts were resolved by the validated specialist result.",
        "evidence_status": "Confirmed"
      },
      {
        "id": "DAT-002",
        "decision": "Use the exact query options $select=name,accountnumber, $filter=statecode eq 0, $orderby=createdon desc, and $top=10.",
        "rationale": "The contract limits data exposure and produces the requested active-account review set.",
        "evidence_status": "Confirmed"
      },
      {
        "id": "DAT-003",
        "decision": "Perform no writes and retain no local copy of returned Account data.",
        "rationale": "The slice is a read-only review experience and does not need duplicate persistence.",
        "evidence_status": "Confirmed"
      }
    ],
    "integration": [
      {
        "id": "INT-001",
        "decision": "Use only the model-driven host's Xrm.WebApi interface; add no connector, custom API, flow, webhook, or external service.",
        "rationale": "A single platform-native read boundary minimizes ownership ambiguity and failure paths.",
        "evidence_status": "Confirmed"
      }
    ],
    "ai": [
      {
        "id": "AI-001",
        "decision": "Include no AI component in this slice.",
        "rationale": "The required outcome is deterministic account retrieval and presentation.",
        "evidence_status": "Confirmed"
      }
    ],
    "security": [
      {
        "id": "SEC-001",
        "decision": "Rely on authenticated model-driven user context and least-privilege Account read access; do not embed credentials or elevate permissions.",
        "rationale": "Dataverse remains the authoritative enforcement boundary while the client handles denied access safely.",
        "evidence_status": "Assumption"
      },
      {
        "id": "SEC-002",
        "decision": "Render returned values as text and keep record data and platform diagnostics out of telemetry and user-visible error details.",
        "rationale": "This limits injection and information-disclosure risks.",
        "evidence_status": "Assumption"
      }
    ],
    "operations": [
      {
        "id": "OPS-001",
        "decision": "Record correlation ID, duration, row count, stale-response signal, and sanitized outcome for each load attempt.",
        "rationale": "These fields support diagnosis without collecting account content or environment-specific identifiers.",
        "evidence_status": "Assumption"
      },
      {
        "id": "OPS-002",
        "decision": "Treat permission failures, query failures, malformed responses, and stale discarded responses as distinct operational outcomes.",
        "rationale": "Distinct outcomes make support evidence actionable while preserving safe user feedback.",
        "evidence_status": "Assumption"
      }
    ],
    "alm": [
      {
        "id": "ALM-001",
        "decision": "Package the client component, model-driven app navigation change, configuration, and dependencies in one solution using the repository's established publisher and pipeline conventions.",
        "rationale": "A single deployable unit enables deterministic promotion and rollback.",
        "evidence_status": "Assumption"
      },
      {
        "id": "ALM-002",
        "decision": "Keep environment-specific telemetry and placement values in supported configuration rather than source constants.",
        "rationale": "This avoids environment-bound artifacts and supports controlled promotion.",
        "evidence_status": "Assumption"
      }
    ]
  },
  "delegations": [
    {
      "id": "DEL-001",
      "specialist": ".agents/skills/dataverse-webapi-query/",
      "source_type": "upstream",
      "phase": "externally-completed",
      "registry": {
        "path": "evaluator-supplied canonical upstream register evidence",
        "entry_status": "current-approved",
        "version_or_pin": "f4bb4ad5bf55e2d50076292bd6301f6337d38083",
        "verified_on": "2026-07-20"
      },
      "request": {
        "scope": "Construct an Xrm.WebApi query for the top ten active synthetic accounts, selecting name and accountnumber and ordering by createdon descending.",
        "data_classification": "synthetic",
        "zone": "personal-openai",
        "permitted_tools": []
      },
      "handoff": {
        "invocation_mode": "explicit-external",
        "input_payload": "Using standard synthetic Microsoft Dataverse Account schema assumptions, build an Xrm.WebApi query for the top 10 active accounts selecting name and accountnumber, ordered by createdon descending. This is synthetic query construction only; do not authenticate, access a tenant, inspect live metadata, or use any tool.",
        "expected_output_schema": ".agents/skills/dataverse-webapi-query/references/answer-output.schema.json",
        "continuation_instruction": "The evaluator executed the specialist in a separate external phase using only the sanitized payload, preserved its complete first output, independently validated its schema and SHA-256, and resumed Skill 6 with the original orchestration state and preserved evidence."
      },
      "control": {
        "enabled": true,
        "selection_mode": "explicit",
        "selector": "$dataverse-webapi-query",
        "client_compatible": true,
        "prerequisites_satisfied": true,
        "boundary_permitted": true,
        "permissions_approved": true
      },
      "execution": {
        "execution_observed": true,
        "result_schema_valid": true,
        "invoked": true,
        "outcome_status": "completed",
        "result_reference": "tests/fixtures/powercat/gold-005-result.json"
      },
      "verification": {
        "specialist_identity_verified": true,
        "register_verified": true,
        "input_classification_verified": true,
        "boundary_verified": true,
        "result_hash_verified": true,
        "result_schema_verified": true,
        "untrusted_input_checked": true,
        "override_attempted": false,
        "result_sha256": "2adfa6cbe497117ebbfbb36957b2581119d486bf1807031cea1f9ecd1360da54",
        "source_path": "tests/fixtures/powercat/gold-005-result.json"
      },
      "evidence_refs": [
        "tests/fixtures/powercat/gold-005-result.json",
        "tests/fixtures/powercat/gold-005-result-provenance.json",
        ".agents/skills/dataverse-webapi-query/references/answer-output.schema.json",
        "approved local-adapter pin 33bc38456abb83f27daad968b748c8085f2a78ef"
      ],
      "open_items": [],
      "next_action": "Carry the validated query contract unchanged into the authorised implementation workflow; do not rerun or simulate the specialist."
    }
  ],
  "acceptance_criteria": [
    {
      "id": "AC-001",
      "given": "More than ten synthetic Account rows exist and at least ten have statecode 0",
      "when": "An authorised reviewer opens Account Review",
      "then": "Exactly ten rows are shown, every row is active, and their createdon values are in non-increasing order.",
      "evidence": "Runtime response inspection against controlled synthetic fixtures plus a screenshot or accessibility-tree capture of the rendered result."
    },
    {
      "id": "AC-002",
      "given": "The approved query returns Account rows",
      "when": "Results are rendered",
      "then": "Only name and accountnumber are exposed as business columns and the client preserves service response order.",
      "evidence": "Source assertion, automated render test, and runtime column inspection."
    },
    {
      "id": "AC-003",
      "given": "No active synthetic accounts are returned",
      "when": "The load completes",
      "then": "The loading state ends and an accessible empty-state message is displayed without an error.",
      "evidence": "Automated empty-response test and runtime empty-state capture."
    },
    {
      "id": "AC-004",
      "given": "The user lacks required Account read access",
      "when": "The query is attempted",
      "then": "No records are rendered, a sanitized permission message is shown, retry is not presented as a privilege workaround, and telemetry records permission-denied without record data.",
      "evidence": "Authorised negative-role runtime test and sanitized telemetry record."
    },
    {
      "id": "AC-005",
      "given": "Two refreshes are initiated and the first response arrives last",
      "when": "Both requests complete",
      "then": "Only the second response is rendered and a stale-response-discarded signal is emitted.",
      "evidence": "Automated deferred-promise concurrency test and telemetry assertion."
    },
    {
      "id": "AC-006",
      "given": "A keyboard or screen-reader user opens and refreshes Account Review",
      "when": "Loading, success, empty, or failure state changes",
      "then": "Focus remains predictable, the result or error status is announced, headings and columns have accessible names, and all actions are keyboard operable.",
      "evidence": "Automated accessibility scan, keyboard test, and screen-reader smoke evidence."
    }
  ],
  "negative_paths": [
    {
      "id": "NP-001",
      "condition": "Xrm.WebApi is unavailable in the selected host.",
      "expected_behavior": "Stop before issuing a request, show a sanitized unsupported-host message, and record unsupported-host telemetry.",
      "evidence": "Unit test with the host API removed."
    },
    {
      "id": "NP-002",
      "condition": "The query rejects because of permission denial.",
      "expected_behavior": "Render no rows, disclose no service payload, show the permission state, and record only the sanitized outcome.",
      "evidence": "Security test with a least-privilege negative role."
    },
    {
      "id": "NP-003",
      "condition": "The query fails transiently.",
      "expected_behavior": "End loading, show a retryable failure with correlation ID, and permit one user-initiated retry without duplicate rendering.",
      "evidence": "Automated rejected-promise and retry test."
    },
    {
      "id": "NP-004",
      "condition": "The response is malformed or lacks the expected collection.",
      "expected_behavior": "Render no partial data, show a generic failure, and emit malformed-response telemetry without the response body.",
      "evidence": "Contract test using malformed synthetic responses."
    },
    {
      "id": "NP-005",
      "condition": "A slower earlier request completes after a later refresh.",
      "expected_behavior": "Discard the earlier response, retain the newer result, and emit the stale-response-discarded signal.",
      "evidence": "Concurrent-response ordering test."
    },
    {
      "id": "NP-006",
      "condition": "Inactive accounts or more than ten eligible accounts exist.",
      "expected_behavior": "Inactive rows are absent and no more than ten rows are rendered.",
      "evidence": "Controlled synthetic dataset test."
    },
    {
      "id": "NP-007",
      "condition": "A returned name or accountnumber contains long text or markup-like characters.",
      "expected_behavior": "Render the value as encoded text, constrain layout without losing accessible access to content, and execute no markup.",
      "evidence": "Security and responsive-layout tests using synthetic edge values."
    }
  ],
  "tests": [
    {
      "id": "TEST-001",
      "class": "functional",
      "scope": "Approved Xrm.WebApi invocation, active filtering, descending ordering, top-ten limit, and two-column rendering.",
      "expected": "The exact approved query is called once per accepted load and the response is rendered in service order.",
      "evidence_required": "Automated query-contract and component tests.",
      "status": "planned"
    },
    {
      "id": "TEST-002",
      "class": "functional",
      "scope": "Loading, empty, success, permission, generic failure, malformed-response, and retry states.",
      "expected": "Each state is exclusive, accessible, and clears or preserves results according to the defined behavior.",
      "evidence_required": "State-transition test results and selected UI captures.",
      "status": "planned"
    },
    {
      "id": "TEST-003",
      "class": "reliability",
      "scope": "Rapid refresh, duplicate initiation, out-of-order completion, and stale-response suppression.",
      "expected": "Only the latest accepted request updates the UI and discarded requests are observable without duplicate rows.",
      "evidence_required": "Deterministic concurrency test output.",
      "status": "planned"
    },
    {
      "id": "TEST-004",
      "class": "security",
      "scope": "Least-privilege denial, text encoding, sanitized errors, and telemetry exclusions.",
      "expected": "Unauthorised data is not rendered, markup is not executed, and telemetry contains none of the excluded fields.",
      "evidence_required": "Negative-role runtime evidence, encoding tests, and telemetry payload inspection.",
      "status": "planned"
    },
    {
      "id": "TEST-005",
      "class": "accessibility",
      "scope": "Keyboard navigation, focus, live-region announcements, grid semantics, zoom, narrow layout, and long content.",
      "expected": "The primary journey remains perceivable and operable without a pointer and has no critical automated accessibility violations.",
      "evidence_required": "Accessibility scan, keyboard checklist, and screen-reader smoke record.",
      "status": "planned"
    },
    {
      "id": "TEST-006",
      "class": "performance",
      "scope": "Initial load and retry with the response capped at ten rows.",
      "expected": "No duplicate request is created by rendering and elapsed time is captured against the implementation team's approved threshold.",
      "evidence_required": "Browser timing and privacy-safe telemetry from the authorised test environment.",
      "status": "planned"
    },
    {
      "id": "TEST-007",
      "class": "alm",
      "scope": "Solution contents, dependencies, environment configuration, and unmanaged-change detection.",
      "expected": "The package contains the intended component and app change only, with valid dependencies and no environment-specific secrets or URLs.",
      "evidence_required": "Solution unpack diff, dependency inspection, and package validation output.",
      "status": "planned"
    },
    {
      "id": "TEST-008",
      "class": "deployment",
      "scope": "Import, app publication, navigation visibility, role access, configuration readback, and runtime smoke test.",
      "expected": "An authorised reviewer can open the deployed slice and retrieve the controlled synthetic result set.",
      "evidence_required": "Import record, configuration readback, access check, and runtime evidence from the target.",
      "status": "not-run"
    },
    {
      "id": "TEST-009",
      "class": "rollback",
      "scope": "Removal or reversion of the Account Review app entry and client component.",
      "expected": "The prior app version is restored without changing Account records.",
      "evidence_required": "Non-production rollback rehearsal and post-rollback app inspection.",
      "status": "not-run"
    }
  ],
  "deployment": {
    "authorization_status": "not-requested",
    "target_zone": "organisational-microsoft",
    "environments": [
      "Authorised development environment",
      "Authorised test environment",
      "Authorised production environment"
    ],
    "prerequisites": [
      "Confirm supported model-driven Xrm.WebApi client component and entry-point pattern",
      "Resolve publisher, solution name, environment names, navigation placement, and telemetry destination",
      "Provide an approved security role with model-driven app access and least-privilege Account read privileges",
      "Prepare controlled synthetic test data covering more than ten active rows, inactive rows, empty results, long content, and equal createdon values",
      "Define the implementation repository location and established build and solution-packaging commands",
      "Approve deployment and rollback owners through the organisational release process",
      "Confirm telemetry retention, access, and payload exclusions"
    ],
    "steps": [
      "Implement the Account Review client and single query-owner module using the validated contract unchanged",
      "Add focused functional, reliability, security, and accessibility tests",
      "Package the client component and model-driven app entry in the designated solution",
      "Inspect unpacked source, dependencies, configuration, and generated package integrity",
      "Import through the authorised pipeline into development and test",
      "Bind configuration, publish the app, assign approved access, and read back configuration",
      "Run runtime acceptance, negative-path, accessibility, telemetry, and rollback checks before production approval",
      "Promote the same validated artifact through the authorised production pipeline"
    ],
    "post_deploy_checks": [
      "Confirm the Account Review entry is visible only to the intended persona",
      "Confirm the exact approved Xrm.WebApi query is issued",
      "Confirm no more than ten active rows appear in descending createdon order",
      "Confirm only name and accountnumber are displayed",
      "Exercise empty, permission, transient failure, retry, and stale-response behavior",
      "Inspect privacy-safe telemetry and verify excluded data is absent",
      "Verify keyboard, focus, live-region, narrow-layout, and long-content behavior",
      "Confirm no Account records were modified"
    ],
    "evidence_required": [
      "Authorised pipeline and import records",
      "Solution package and dependency inspection",
      "Configuration and app-publication readback",
      "Security-role access evidence",
      "Runtime acceptance and negative-path results",
      "Accessibility evidence",
      "Sanitized telemetry samples",
      "Rollback rehearsal or approved rollback verification"
    ]
  },
  "rollback": {
    "triggers": [
      "Account Review prevents the model-driven app from loading or navigating reliably",
      "The deployed query differs from the validated contract",
      "Inactive or more than ten Account rows are exposed",
      "Unauthorised users can access results",
      "Record content or environment-specific identifiers appear in telemetry",
      "Critical accessibility or stale-response defects remain after deployment"
    ],
    "steps": [
      "Disable or remove the Account Review navigation entry using the authorised release process",
      "Reimport or reactivate the previously approved solution and model-driven app version",
      "Publish the restored app and verify intended persona access",
      "Confirm Account Review requests and telemetry have stopped",
      "Record the sanitized failure evidence and retain the failed artifact for controlled diagnosis"
    ],
    "data_considerations": [
      "The slice performs no Dataverse writes, so rollback requires no Account data reversal",
      "Do not delete Account records or telemetry as part of component rollback",
      "Apply organisational telemetry retention and access policy to already emitted sanitized events"
    ],
    "owner": "Authorised Power Platform release owner",
    "evidence_required": [
      "Rollback authorization and pipeline record",
      "Restored solution and app-version readback",
      "Post-rollback navigation and access verification",
      "Confirmation that no Account data changed"
    ]
  },
  "next_action": "Hand this Ready brief and the unchanged validated Xrm.WebApi query contract to an authorised implementation workflow; first confirm the supported model-driven client component, repository conventions, publisher, target environments, security role, and telemetry configuration, without authenticating, deploying, or rerunning the specialist in this workflow."
}
